head.b:skin:
/* <Variable name="page.background" description="Page background" type="color" default="#1c241e" value="#1c241e"/><Variable name="page.text" description="Text color" type="color" default="#e9dfc6" value="#e9dfc6"/><Variable name="theme.accent" description="Accent color" type="color" default="#d5b67c" value="#d5b67c"/> */
/* Blogger stylesheet compatibility: restore the spacing Blogger's own widget stylesheet removes, and keep post content inside a phone screen. */
h1{margin:.67em 0}h2{margin:.83em 0}h3{margin:1em 0}h4{margin:1.33em 0}h1,h2,h3,h4,a img{position:static}body{padding:0;word-break:normal}.post-body{width:auto;overflow-x:auto}.post-body a[style*='margin-left'],.post-body a[style*='margin-right']{margin-inline:0!important}.post-body .separator,.post-body .tr-caption-container{max-width:100%}.widget .post-body ul,.widget .post-body ol{margin:1em 0;padding:0 0 0 1.4em;line-height:inherit}.widget .post-body li{margin:0 0 .35em;padding:0}.latest-empty{display:none}.single-view{font-size:1rem}.single-view .post-title{overflow-wrap:anywhere}
:root{--bg:$(page.background);--ink:$(page.text);--accent:$(theme.accent);--heading:'Spectral', Georgia, serif;--body:Georgia, serif}
*{box-sizing:border-box}body{margin:0;background:var(--bg);color:var(--ink);font:16px/1.6 var(--body)}h1,h2,h3{font-family:var(--heading);line-height:1.15}a{color:inherit;text-underline-offset:4px}a:hover{text-decoration-thickness:2px}img{max-width:100%;height:auto}svg{max-width:100%;height:auto}button,input{font:inherit}a:focus-visible,button:focus-visible,summary:focus-visible,input:focus-visible{outline:3px solid currentColor;outline-offset:5px}a,button,summary{touch-action:manipulation}nav{max-width:100%}p,h1,h2,h3,a{overflow-wrap:anywhere}.skip-link{position:fixed;top:-100px;left:16px;z-index:100;background:var(--ink);color:var(--bg);padding:12px}.skip-link:focus{top:12px}.section,.widget{min-width:0;margin:0;padding:0;line-height:inherit}.latest{max-width:1200px;margin:64px auto;padding:0 24px}.posts-grid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:28px}.post-card{min-width:0}.post-title a{text-decoration:none}.post-title a:hover{text-decoration:underline}.post-media{display:block;aspect-ratio:16/10;overflow:hidden;background:color-mix(in srgb,var(--accent) 12%,var(--bg))}.post-media img{width:100%;height:100%;object-fit:cover}.post-art{height:100%;display:grid;place-items:center;font:italic 70px var(--heading);color:var(--accent)}.post-meta{margin-top:18px;font-size:12px}.post-meta a{margin-right:12px}.pager{display:flex;justify-content:space-between;gap:20px;margin-top:40px;padding-top:20px;border-top:1px solid currentColor}.pager a{padding:10px 0}.post-body{max-width:70ch;margin-inline:auto;overflow-wrap:anywhere}.post-body img,.post-body iframe{max-width:100%}.post-body pre,.post-body table{display:block;overflow:auto;max-width:100%}.single-view .latest{max-width:900px}.single-view .section-heading{display:none}.single-view .post-title{font-size:clamp(32px,5vw,62px)}.single-view #comments{margin-top:60px}.empty-state,.error-state{padding:45px 0}.error-state{max-width:900px;margin:auto;padding:70px 24px}.listing-heading{font-size:clamp(28px,5vw,52px)}#Attribution1,.widget.Attribution{display:none!important}@media(max-width:700px){.posts-grid{grid-template-columns:1fr}.latest{margin:45px auto}.pager{flex-wrap:wrap}}
.site-header{margin:0 5%;padding:30px 0;display:flex;align-items:center;justify-content:space-between;border-bottom:1px solid #626a50}.brand{font:22px 'Spectral', Georgia,serif;color:#d5b67c}nav{display:flex;gap:30px;font:11px Arial,sans-serif}.book-welcome{text-align:center;padding:48px 5% 0;position:relative}.book-eyebrow{font:9px Arial,sans-serif;letter-spacing:2.5px;text-transform:uppercase;color:#d5b67c}.book-welcome h1{font:normal clamp(53px,6.6vw,86px)/1.05 'Spectral', Georgia,serif;letter-spacing:-3px;margin:35px 0 25px}.book-welcome>p:not(.book-eyebrow){font-size:16px;line-height:1.7;color:#c0c3ad}.book-welcome>a{display:inline-block;font:11px Arial,sans-serif;border-bottom:1px solid #d5b67c;padding-bottom:8px;margin-top:15px;color:#d5b67c}.book-illustration{max-width:860px;margin:40px auto 0}.book-illustration svg{display:block;width:100%}.book-invitation{padding:45px 8%;background:#e2d7b9;color:#2a3529;text-align:center}.book-invitation>span{font:9px Arial,sans-serif;letter-spacing:3px}.book-invitation blockquote{font:italic 35px/1.25 'Spectral', Georgia,serif;margin:25px 0}.book-invitation p{font-size:13px}.book-shelves{padding:65px 7%;display:grid;grid-template-columns:1fr 2fr;gap:50px}.book-shelves h2{font:normal 43px/1.1 'Spectral', Georgia,serif}.shelf-list a{display:flex;align-items:center;gap:23px;border-bottom:1px solid #626a50;padding:22px 0}.shelf-list i{color:#d5b67c;font-size:18px;min-width:25px}.shelf-list span{font-size:22px}.shelf-list small{display:block;font:11px Arial,sans-serif;color:#c0c3ad;margin-top:10px}.shelf-list b{margin-left:auto;color:#d5b67c;font-weight:400}.latest{padding:10px 7% 65px}.section-heading{font:italic 32px 'Spectral', Georgia,serif;border-bottom:1px solid #626a50;padding-bottom:20px}.posts-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:30px}.post-card{border:1px solid #626a50;padding:20px;background:#242e25}.post-media{aspect-ratio:4/3;object-fit:cover;background:#4c5942}.post-meta{font:9px Arial,sans-serif;color:#d5b67c;text-transform:uppercase;letter-spacing:1px}.post-title{font:normal 25px/1.2 'Spectral', Georgia,serif}.post-excerpt{font-size:13px;color:#c0c3ad;line-height:1.8}.book-bottom{margin:0 7% 60px;border:1px solid #8f845e;padding:50px;text-align:center;background:radial-gradient(ellipse at top,#354130,transparent 70%)}.book-bottom h2{font:normal 51px/1.1 'Spectral', Georgia,serif}.book-bottom p:not(.book-eyebrow){font-size:14px;color:#c0c3ad;max-width:400px;margin:auto;line-height:1.8}.book-bottom a{display:inline-block;margin-top:25px;font:11px Arial,sans-serif;color:#d5b67c;border-bottom:1px solid;padding-bottom:7px}.site-footer{margin:0 5%;padding:30px 0;border-top:1px solid #626a50;display:flex;align-items:center;justify-content:space-between;gap:20px;font:10px Arial,sans-serif;color:#c0c3ad}.site-footer strong{font:20px 'Spectral', Georgia,serif;color:#d5b67c}a:hover,a:focus-visible{color:#f4dca0}@media(max-width:700px){.site-header{flex-direction:column;gap:24px}nav{gap:18px}.book-welcome h1{font-size:57px}.book-shelves{grid-template-columns:1fr;gap:8px;padding:40px 6%}.book-shelves h2 br{display:none}.posts-grid{grid-template-columns:1fr}.book-bottom{padding:30px 20px}.book-bottom h2{font-size:43px}.book-invitation blockquote{font-size:28px}.site-footer{flex-direction:column}}
:focus-visible{outline:2px solid currentColor;outline-offset:5px}img,svg{max-width:100%}@media(prefers-reduced-motion:reduce){*,*::before,*::after{animation:none!important;transition:none!important;scroll-behavior:auto!important}}
h1,h2,h3{font-family:'Spectral', Georgia, serif}
@media(prefers-reduced-motion:reduce){html{scroll-behavior:auto!important}*,*::before,*::after{animation:none!important;transition:none!important}.post-media img{transform:none!important}}@media print{nav,.skip-link,.pager{display:none!important}body{background:white;color:black}}
